import{_ as p,a0 as o,w as r,s as d,ao as l,I as t,x as e,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"30 个 Openstack 经典面试问题和解答 | LCTT x X-CMD","titleTemplate":false,"description":"30 个 Openstack 经典面试问题和解答 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"30 个 Openstack 经典面试问题和解答 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"30 个 Openstack 经典面试问题和解答 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181107 Top 30 OpenStack Interview Questions and Answers","title":"30 个 Openstack 经典面试问题和解答","tag":"201812","desc":""},"relativePath":"201812/20181107 Top 30 OpenStack Interview Questions and Answers.md","filePath":"[post].md"}'),c={name:"201812/20181107 Top 30 OpenStack Interview Questions and Answers.md"};function h(k,a,g,b,u,f){const s=o("Link");return r(),d("div",null,[a[20]||(a[20]=l('<h1 id="_30-个-openstack-经典面试问题和解答" tabindex="-1">30 个 Openstack 经典面试问题和解答 <a class="header-anchor" href="#_30-个-openstack-经典面试问题和解答" aria-label="Permalink to “30 个 Openstack 经典面试问题和解答”">​</a></h1><p>现在，大多数公司都试图将它们的 IT 基础设施和电信设施迁移到私有云， 如 OpenStack。如果你打算面试 OpenStack 管理员这个岗位，那么下面列出的这些面试问题可能会帮助你通过面试。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/11/OpenStack-Interview-Questions.jpg" alt=""></p><h3 id="q-1-说一下-openstack-及其主要组件" tabindex="-1">Q:1 说一下 OpenStack 及其主要组件？ <a class="header-anchor" href="#q-1-说一下-openstack-及其主要组件" aria-label="Permalink to “Q:1 说一下 OpenStack 及其主要组件？”">​</a></h3><p>答： OpenStack 是一系列开源软件，这些软件组成了一个云供给软件，也就是 OpenStack，意即开源软件或项目栈。</p><p>下面是 OpenStack 的主要关键组件：</p><ul><li><strong>Nova</strong> – 用于在计算级别管理虚拟机，并在计算或管理程序级别执行其他计算任务。</li><li><strong>Neutron</strong> – 为虚拟机、计算和控制节点提供网络功能。</li><li><strong>Keystone</strong> – 为所有云用户和 OpenStack 云服务提供身份认证服务。换句话说，我们可以说 Keystone 是一个提供给云用户和云服务访问权限的方法。</li><li><strong>Horizon</strong> – 用于提供图形用户界面。使用图形化管理界面可以很轻松地完成各种日常操作任务。</li><li><strong>Cinder</strong> – 用于提供块存储功能。通常来说 OpenStack 的 Cinder 中集成了 Chef 和 ScaleIO 来共同为计算和控制节点提供块存储服务。</li><li><strong>Swift</strong> – 用于提供对象存储功能。通常来说，Glance 管理的镜像是存储在对象存储空间的。像 ScaleIO 这样的外部存储也可以提供对象存储，可以很容易的集成 Glance 服务。</li><li><strong>Glance</strong> – 用于提供镜像服务。使用 Glance 的管理平台来上传和下载云镜像。</li><li><strong>Heat</strong> – 用于提供编排服务或功能。使用 Heat 管理平台可以轻松地将虚拟机作为堆栈，并且根据需要可以将虚拟机扩展或收缩。</li><li><strong>Ceilometer</strong> – 用于提供计量与监控功能。</li></ul><h3 id="q-2-什么服务通常在控制节点上运行" tabindex="-1">Q:2 什么服务通常在控制节点上运行？ <a class="header-anchor" href="#q-2-什么服务通常在控制节点上运行" aria-label="Permalink to “Q:2 什么服务通常在控制节点上运行？”">​</a></h3><p>答： 以下服务通常在控制节点上运行：</p><ul><li>认证服务（KeyStone）</li><li>镜像服务（Glance）</li><li>Nova 服务比如 Nova API、Nova Scheduler 和 Nova DB</li><li>块存储和对象存储服务</li><li>Ceilometer 服务</li><li>MariaDB / MySQL 和 RabbitMQ 服务</li><li>网络(Neutron)和网络代理的管理服务</li><li>编排服务（Heat）</li></ul><h3 id="q-3-什么服务通常在计算节点上运行" tabindex="-1">Q:3 什么服务通常在计算节点上运行？ <a class="header-anchor" href="#q-3-什么服务通常在计算节点上运行" aria-label="Permalink to “Q:3 什么服务通常在计算节点上运行？”">​</a></h3><p>答： 以下服务通常在计算节点运行：</p><ul><li>Nova 计算</li><li>网络服务，比如 OVS</li></ul><h3 id="q-4-计算节点上虚拟机的默认地址是什么" tabindex="-1">Q:4 计算节点上虚拟机的默认地址是什么? <a class="header-anchor" href="#q-4-计算节点上虚拟机的默认地址是什么" aria-label="Permalink to “Q:4 计算节点上虚拟机的默认地址是什么?”">​</a></h3><p>答： 虚拟机存储在计算节点的 <code>/var/lib/nova/instances</code>。</p><h3 id="q-5-glance-镜像的默认地址是什么" tabindex="-1">Q:5 Glance 镜像的默认地址是什么？ <a class="header-anchor" href="#q-5-glance-镜像的默认地址是什么" aria-label="Permalink to “Q:5 Glance 镜像的默认地址是什么？”">​</a></h3><p>答： 因为 Glance 服务运行在控制节点上，所以 Glance 镜像都被存储在控制节点的 <code>/var/lib/glance/images</code> 文件夹下。</p>',17)),t("p",null,[a[1]||(a[1]=e("想了解更多请访问：",-1)),i(s,{href:"https://www.linuxtechi.com/create-delete-virtual-machine-command-line-openstack/"},{default:n(()=>[...a[0]||(a[0]=[e("在 OpenStack 中如何使用命令行创建和删除虚拟机",-1)])]),_:1})]),a[21]||(a[21]=l(`<h3 id="q-6-说一下如何使用命令行启动一个虚拟机" tabindex="-1">Q:6 说一下如何使用命令行启动一个虚拟机？ <a class="header-anchor" href="#q-6-说一下如何使用命令行启动一个虚拟机" aria-label="Permalink to “Q:6 说一下如何使用命令行启动一个虚拟机？”">​</a></h3><p>答： 我们可以使用如下 OpenStack 命令来启动一个新的虚拟机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># openstack server create --flavor {flavor-name} --image {Image-Name-Or-Image-ID}  --nic net-id={Network-ID} --security-group {Security_Group_ID} –key-name {Keypair-Name} &lt;VM_Name&gt;</span></span></code></pre></div><h3 id="q-7-如何在-openstack-中显示用户的网络命名空间列表" tabindex="-1">Q:7 如何在 OpenStack 中显示用户的网络命名空间列表？ <a class="header-anchor" href="#q-7-如何在-openstack-中显示用户的网络命名空间列表" aria-label="Permalink to “Q:7 如何在 OpenStack 中显示用户的网络命名空间列表？”">​</a></h3><p>答： 可以使用 <code>ip net ns</code> 命令来列出用户的网络命名空间。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# ip netns list</span></span>
<span class="line"><span>qdhcp-a51635b1-d023-419a-93b5-39de47755d2d</span></span>
<span class="line"><span>haproxy</span></span>
<span class="line"><span>vrouter</span></span></code></pre></div><h3 id="q-8-如何在-openstack-中执行网络命名空间内的命令" tabindex="-1">Q:8 如何在 OpenStack 中执行网络命名空间内的命令？ <a class="header-anchor" href="#q-8-如何在-openstack-中执行网络命名空间内的命令" aria-label="Permalink to “Q:8 如何在 OpenStack 中执行网络命名空间内的命令？”">​</a></h3><p>答： 假设我们想在 <code>qdhcp-a51635b1-d023-419a-93b5-39de47755d2d</code> 网络命名空间中执行 <code>ifconfig</code> 命令，我们可以执行如下命令。</p><p>命令格式 : <code>ip netns exec {network-space} &lt;command&gt;</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# ip netns exec qdhcp-a51635b1-d023-419a-93b5-39de47755d2d &quot;ifconfig&quot;</span></span></code></pre></div><h3 id="q-9-在-glance-服务中如何使用命令行上传和下载镜像" tabindex="-1">Q:9 在 Glance 服务中如何使用命令行上传和下载镜像？ <a class="header-anchor" href="#q-9-在-glance-服务中如何使用命令行上传和下载镜像" aria-label="Permalink to “Q:9 在 Glance 服务中如何使用命令行上传和下载镜像？”">​</a></h3><p>答： Glance 服务中云镜像上传可以使用如下 OpenStack 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack image create --disk-format qcow2 --container-format bare   --public --file {Name-Cloud-Image}.qcow2     &lt;Cloud-Image-Name&gt;</span></span></code></pre></div><p>下载云镜像则使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# glance image-download --file &lt;Cloud-Image-Name&gt; --progress  &lt;Image-ID&gt;</span></span></code></pre></div><h3 id="q-10-openstack-如何将虚拟机从错误状态转换为活动状态" tabindex="-1">Q:10 OpenStack 如何将虚拟机从错误状态转换为活动状态？ <a class="header-anchor" href="#q-10-openstack-如何将虚拟机从错误状态转换为活动状态" aria-label="Permalink to “Q:10 OpenStack 如何将虚拟机从错误状态转换为活动状态？”">​</a></h3><p>答： 在某些情况下虚拟机可能会进入错误状态，可以使用如下命令将错误状态转换为活动状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# nova reset-state --active {Instance_id}</span></span></code></pre></div><h3 id="q-11-如何使用命令行来获取可使用的浮动-ip-列表" tabindex="-1">Q:11 如何使用命令行来获取可使用的浮动 IP 列表？ <a class="header-anchor" href="#q-11-如何使用命令行来获取可使用的浮动-ip-列表" aria-label="Permalink to “Q:11 如何使用命令行来获取可使用的浮动 IP 列表？”">​</a></h3><p>答： 可使用如下命令来显示可用浮动 IP 列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~]# openstack ip floating list | grep None | head -10</span></span></code></pre></div><h3 id="q-12-如何在特定可用区域中或在计算主机上配置虚拟机" tabindex="-1">Q:12 如何在特定可用区域中或在计算主机上配置虚拟机？ <a class="header-anchor" href="#q-12-如何在特定可用区域中或在计算主机上配置虚拟机" aria-label="Permalink to “Q:12 如何在特定可用区域中或在计算主机上配置虚拟机？”">​</a></h3><p>答： 假设我们想在 compute-02 中的可用区 NonProduction 上配置虚拟机，可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~]# openstack server create --flavor m1.tiny --image cirros --nic net-id=e0be93b8-728b-4d4d-a272-7d672b2560a6 --security-group NonProd_SG  --key-name linuxtec --availability-zone NonProduction:compute-02  nonprod_testvm</span></span></code></pre></div><h3 id="q-13-如何在特定计算节点上获取配置的虚拟机列表" tabindex="-1">Q:13 如何在特定计算节点上获取配置的虚拟机列表？ <a class="header-anchor" href="#q-13-如何在特定计算节点上获取配置的虚拟机列表" aria-label="Permalink to “Q:13 如何在特定计算节点上获取配置的虚拟机列表？”">​</a></h3><p>答： 假设我们想要获取在 compute-0-19 中配置的虚拟机列表，可以使用如下命令：</p><p>命令格式: <code>openstack server list –all-projects –long -c Name -c Host | grep -i {Compute-Node-Name}</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack server list --all-projects --long -c Name -c Host | grep -i  compute-0-19</span></span></code></pre></div><h3 id="q-14-如何使用命令行查看-openstack-实例的控制台日志" tabindex="-1">Q:14 如何使用命令行查看 OpenStack 实例的控制台日志？ <a class="header-anchor" href="#q-14-如何使用命令行查看-openstack-实例的控制台日志" aria-label="Permalink to “Q:14 如何使用命令行查看 OpenStack 实例的控制台日志？”">​</a></h3><p>答： 使用如下命令可查看实例的控制台日志。</p><p>首先获取实例的 ID，然后使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack console log show {Instance-id}</span></span></code></pre></div><h3 id="q-15-如何获取-openstack-实例的控制台的-url-地址" tabindex="-1">Q:15 如何获取 OpenStack 实例的控制台的 URL 地址？ <a class="header-anchor" href="#q-15-如何获取-openstack-实例的控制台的-url-地址" aria-label="Permalink to “Q:15 如何获取 OpenStack 实例的控制台的 URL 地址？”">​</a></h3><p>答： 可以使用以下 OpenStack 命令从命令行检索实例的控制台 URL 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack console url show {Instance-id}</span></span></code></pre></div><h3 id="q-16-如何使用命令行创建可启动的-cinder-block-存储卷" tabindex="-1">Q:16 如何使用命令行创建可启动的 cinder / block 存储卷？ <a class="header-anchor" href="#q-16-如何使用命令行创建可启动的-cinder-block-存储卷" aria-label="Permalink to “Q:16 如何使用命令行创建可启动的 cinder / block 存储卷？”">​</a></h3><p>答： 假设创建一个 8GB 可启动存储卷，可参考如下步骤：</p><ul><li><p>使用如下命令获取镜像列表</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span></code></pre></div></li></ul><p>~# openstack image list | grep -i cirros | 89254d46-a54b-4bc8-8e4d-658287c7ee92 | cirros  | active |</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  *  使用 cirros 镜像创建 8GB 的可启动存储卷</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    \`\`\`</span></span>
<span class="line"><span>~# cinder create --image-id 89254d46-a54b-4bc8-8e4d-658287c7ee92 --display-name cirros-bootable-vol  8</span></span></code></pre></div><h3 id="q-17-如何列出所有在你的-openstack-中创建的项目或用户" tabindex="-1">Q:17 如何列出所有在你的 OpenStack 中创建的项目或用户？ <a class="header-anchor" href="#q-17-如何列出所有在你的-openstack-中创建的项目或用户" aria-label="Permalink to “Q:17 如何列出所有在你的 OpenStack 中创建的项目或用户？”">​</a></h3><p>答： 可以使用如下命令来检索所有项目和用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack project list --long</span></span></code></pre></div><h3 id="q-18-如何显示-openstack-服务端点列表" tabindex="-1">Q:18 如何显示 OpenStack 服务端点列表？ <a class="header-anchor" href="#q-18-如何显示-openstack-服务端点列表" aria-label="Permalink to “Q:18 如何显示 OpenStack 服务端点列表？”">​</a></h3><p>答： OpenStack 服务端点被分为 3 类：</p><ul><li>公共端点</li><li>内部端点</li><li>管理端点</li></ul><p>使用如下 OpenStack 命令来查看各种 OpenStack 服务端点：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack catalog list</span></span></code></pre></div><p>可通过以下命令来显示特定服务端点（比如说 keystone）列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack catalog show keystone</span></span></code></pre></div>`,50)),t("p",null,[a[3]||(a[3]=e("想了解更多请访问：",-1)),i(s,{href:"https://www.linuxtechi.com/step-by-step-instance-creation-flow-in-openstack/"},{default:n(()=>[...a[2]||(a[2]=[e("OpenStack 中的实例创建流程",-1)])]),_:1}),a[4]||(a[4]=e("。",-1))]),a[22]||(a[22]=l(`<h3 id="q-19-在控制节点上你应该按照什么步骤来重启-nova-服务" tabindex="-1">Q:19 在控制节点上你应该按照什么步骤来重启 nova 服务？ <a class="header-anchor" href="#q-19-在控制节点上你应该按照什么步骤来重启-nova-服务" aria-label="Permalink to “Q:19 在控制节点上你应该按照什么步骤来重启 nova 服务？”">​</a></h3><p>答： 应该按照如下步骤来重启 OpenStack 控制节点的 nova 服务：</p><ul><li><code>service nova-api restart</code></li><li><code>service nova-cert restart</code></li><li><code>service nova-conductor restart</code></li><li><code>service nova-consoleauth restart</code></li><li><code>service nova-scheduler restart</code></li></ul><h3 id="q-20-假如计算节点上为数据流量配置了一些-dpdk-端口-你如何检查-dpdk-端口的状态呢" tabindex="-1">Q:20 假如计算节点上为数据流量配置了一些 DPDK 端口，你如何检查 DPDK 端口的状态呢？ <a class="header-anchor" href="#q-20-假如计算节点上为数据流量配置了一些-dpdk-端口-你如何检查-dpdk-端口的状态呢" aria-label="Permalink to “Q:20 假如计算节点上为数据流量配置了一些 DPDK 端口，你如何检查 DPDK 端口的状态呢？”">​</a></h3><p>答： 因为我们使用 openvSwitch (OVS) 来配置 DPDK 端口，因此可以使用如下命令来检查端口的状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@compute-0-15:~# ovs-appctl bond/show | grep dpdk</span></span>
<span class="line"><span>active slave mac: 90:38:09:ac:7a:99(dpdk0)</span></span>
<span class="line"><span>slave dpdk0: enabled</span></span>
<span class="line"><span>slave dpdk1: enabled</span></span>
<span class="line"><span>root@compute-0-15:~#</span></span>
<span class="line"><span>root@compute-0-15:~# dpdk-devbind.py --status</span></span></code></pre></div><h3 id="q-21-如何使用命令行在-openstack-中向存在的安全组-sg-安全组-中添加新规则" tabindex="-1">Q:21 如何使用命令行在 OpenStack 中向存在的安全组 SG（安全组）中添加新规则？ <a class="header-anchor" href="#q-21-如何使用命令行在-openstack-中向存在的安全组-sg-安全组-中添加新规则" aria-label="Permalink to “Q:21 如何使用命令行在 OpenStack 中向存在的安全组 SG（安全组）中添加新规则？”">​</a></h3><p>答： 可以使用 <code>neutron</code> 命令向 OpenStack 已存在的安全组中添加新规则：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# neutron security-group-rule-create --protocol &lt;tcp or udp&gt;  --port-range-min &lt;port-number&gt; --port-range-max &lt;port-number&gt; --direction &lt;ingress or egress&gt;  --remote-ip-prefix &lt;IP-address-or-range&gt; Security-Group-Name</span></span></code></pre></div><h3 id="q-22-如何查看控制节点和计算节点的-ovs-桥配置" tabindex="-1">Q:22 如何查看控制节点和计算节点的 OVS 桥配置？ <a class="header-anchor" href="#q-22-如何查看控制节点和计算节点的-ovs-桥配置" aria-label="Permalink to “Q:22 如何查看控制节点和计算节点的 OVS 桥配置？”">​</a></h3><p>答： 控制节点和计算节点的 OVS 桥配置可使用以下命令来查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~]# ovs-vsctl show</span></span></code></pre></div><h3 id="q-23-计算节点上的集成桥-br-int-的作用是什么" tabindex="-1">Q:23 计算节点上的集成桥（br-int）的作用是什么？ <a class="header-anchor" href="#q-23-计算节点上的集成桥-br-int-的作用是什么" aria-label="Permalink to “Q:23 计算节点上的集成桥（br-int）的作用是什么？”">​</a></h3><p>答： 集成桥（br-int）对来自和运行在计算节点上的实例的流量执行 VLAN 标记和取消标记。</p><p>数据包从实例的 n/w 接口发出使用虚拟接口 qvo 通过 Linux 桥（qbr）。qvb 接口是用来连接 Linux 桥的，qvo 接口是用来连接集成桥的。集成桥上的 qvo 端口有一个内部 VLAN 标签，这个标签是用于当数据包到达集成桥的时候贴到数据包头部的。</p><h3 id="q-24-隧道桥-br-tun-在计算节点上的作用是什么" tabindex="-1">Q:24 隧道桥（br-tun）在计算节点上的作用是什么？ <a class="header-anchor" href="#q-24-隧道桥-br-tun-在计算节点上的作用是什么" aria-label="Permalink to “Q:24 隧道桥（br-tun）在计算节点上的作用是什么？”">​</a></h3><p>答： 隧道桥（br-tun）根据 OpenFlow 规则将 VLAN 标记的流量从集成网桥转换为隧道 ID。</p><p>隧道桥允许不同网络的实例彼此进行通信。隧道有利于封装在非安全网络上传输的流量，它支持两层网络，即 GRE 和 VXLAN。</p><h3 id="q-25-外部-ovs-桥-br-ex-的作用是什么" tabindex="-1">Q:25 外部 OVS 桥（br-ex）的作用是什么？ <a class="header-anchor" href="#q-25-外部-ovs-桥-br-ex-的作用是什么" aria-label="Permalink to “Q:25 外部 OVS 桥（br-ex）的作用是什么？”">​</a></h3><p>答： 顾名思义，此网桥转发来往网络的流量，以允许外部访问实例。br-ex 连接物理接口比如 eth2，这样用户网络的浮动 IP 数据从物理网络接收并路由到用户网络端口。</p><h3 id="q-26-openstack-网络中-openflow-规则的作用是什么" tabindex="-1">Q:26 OpenStack 网络中 OpenFlow 规则的作用是什么？ <a class="header-anchor" href="#q-26-openstack-网络中-openflow-规则的作用是什么" aria-label="Permalink to “Q:26  OpenStack 网络中 OpenFlow 规则的作用是什么？”">​</a></h3><p>答： OpenFlow 规则是一种机制，这种机制定义了一个数据包如何从源到达目的地。OpenFlow 规则存储在 flow 表中。flow 表是 OpenFlow 交换机的一部分。</p><p>当一个数据包到达交换机就会被第一个 flow 表检查，如果不匹配 flow 表中的任何入口，那这个数据包就会被丢弃或者转发到其他 flow 表中。</p><h3 id="q-27-怎样查看-openflow-交换机的信息-比如端口、表编号、缓存编号等" tabindex="-1">Q:27 怎样查看 OpenFlow 交换机的信息（比如端口、表编号、缓存编号等）？ <a class="header-anchor" href="#q-27-怎样查看-openflow-交换机的信息-比如端口、表编号、缓存编号等" aria-label="Permalink to “Q:27 怎样查看 OpenFlow 交换机的信息（比如端口、表编号、缓存编号等）？”">​</a></h3><p>答： 假如我们要显示 OpenFlow 交换机的信息（br-int），需要执行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@compute-0-15# ovs-ofctl show br-int</span></span>
<span class="line"><span>OFPT_FEATURES_REPLY (xid=0x2): dpid:0000fe981785c443</span></span>
<span class="line"><span>n_tables:254, n_buffers:256</span></span>
<span class="line"><span>capabilities: FLOW_STATS TABLE_STATS PORT_STATS QUEUE_STATS ARP_MATCH_IP</span></span>
<span class="line"><span>actions: output enqueue set_vlan_vid set_vlan_pcp strip_vlan mod_dl_src mod_dl_dst mod_nw_src mod_nw_dst mod_nw_tos mod_tp_src mod_tp_dst</span></span>
<span class="line"><span> 1(patch-tun): addr:3a:c6:4f:bd:3e:3b</span></span>
<span class="line"><span>     config:     0</span></span>
<span class="line"><span>     state:      0</span></span>
<span class="line"><span>     speed: 0 Mbps now, 0 Mbps max</span></span>
<span class="line"><span> 2(qvob35d2d65-f3): addr:b2:83:c4:0b:42:3a</span></span>
<span class="line"><span>     config:     0</span></span>
<span class="line"><span>     state:      0</span></span>
<span class="line"><span>     current:    10GB-FD COPPER</span></span>
<span class="line"><span>     speed: 10000 Mbps now, 0 Mbps max</span></span>
<span class="line"><span> ………………………………………</span></span></code></pre></div><h3 id="q-28-如何显示交换机中的所有-flow-的入口" tabindex="-1">Q:28 如何显示交换机中的所有 flow 的入口？ <a class="header-anchor" href="#q-28-如何显示交换机中的所有-flow-的入口" aria-label="Permalink to “Q:28 如何显示交换机中的所有 flow 的入口？”">​</a></h3><p>答： 可以使用命令 <code>ovs-ofctl dump-flows</code> 来查看交换机的 flow 入口。</p><p>假设我们想显示 OVS 集成桥（br-int）的所有 flow 入口，可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@compute01 ~]# ovs-ofctl dump-flows br-int</span></span></code></pre></div><h3 id="q-29-什么是-neutron-代理-如何显示所有-neutron-代理" tabindex="-1">Q:29 什么是 Neutron 代理？如何显示所有 Neutron 代理？ <a class="header-anchor" href="#q-29-什么是-neutron-代理-如何显示所有-neutron-代理" aria-label="Permalink to “Q:29 什么是 Neutron 代理？如何显示所有 Neutron 代理？”">​</a></h3><p>答： OpenStack Neutron 服务器充当中心控制器，实际网络配置是在计算节点或者网络节点上执行的。Neutron 代理是计算节点或者网络节点上进行配置更新的软件实体。Neutron 代理通过 Neuron 服务和消息队列来和中心 Neutron 服务通信。</p><p>可通过如下命令查看 Neutron 代理列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~# openstack network agent list -c ‘Agent type’ -c Host -c Alive -c State</span></span></code></pre></div><h3 id="q-30-cpu-pinning-是什么" tabindex="-1">Q:30 CPU Pinning 是什么？ <a class="header-anchor" href="#q-30-cpu-pinning-是什么" aria-label="Permalink to “Q:30 CPU Pinning 是什么？”">​</a></h3><p>答： CPU Pinning 是指为某个虚拟机保留物理核心。它也称为 CPU 隔离或处理器关联。有两个目的：</p><ul><li>它确保虚拟机只能在专用核心上运行</li><li>它还确保公共主机进程不在这些核心上运行</li></ul><p>我们也可以认为 Pinning 是物理核心到一个用户虚拟 CPU（vCPU）的一对一映射。</p><hr>`,39)),t("p",null,[a[6]||(a[6]=e("via: ",-1)),i(s,{href:"https://www.linuxtechi.com/openstack-interview-questions-answers/"},{default:n(()=>[...a[5]||(a[5]=[e("https://www.linuxtechi.com/openstack-interview-questions-answers/",-1)])]),_:1})]),t("p",null,[a[11]||(a[11]=e("作者：",-1)),i(s,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...a[7]||(a[7]=[e("Pradeep Kumar",-1)])]),_:1}),a[12]||(a[12]=e(" 选题：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[8]||(a[8]=[e("lujun9972",-1)])]),_:1}),a[13]||(a[13]=e(" 译者：",-1)),i(s,{href:"https://github.com/ScarboroughCoral"},{default:n(()=>[...a[9]||(a[9]=[e("ScarboroughCoral",-1)])]),_:1}),a[14]||(a[14]=e(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:n(()=>[...a[10]||(a[10]=[e("wxy",-1)])]),_:1})]),t("p",null,[a[17]||(a[17]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[15]||(a[15]=[e("LCTT",-1)])]),_:1}),a[18]||(a[18]=e(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:n(()=>[...a[16]||(a[16]=[e("Linux中国",-1)])]),_:1}),a[19]||(a[19]=e(" 荣誉推出",-1))])])}const y=p(c,[["render",h]]);export{x as __pageData,y as default};
